//! Provisional reservation record: identity/proof, never loaded/Start/play.
use crate::{startup_local::Scope,protocol_waiting::{self as protocol,wire as w},secrets::CredentialStore,protected_chunks};
use serde::{Serialize,Deserialize};use zeroize::Zeroize;
#[derive(Clone,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Record{pub scope:Scope,pub world:uuid::Uuid,pub original_session:String,pub request:w::Request,pub fingerprint:String,pub intent:Option<w::PendingIntent>,pub proof:Option<String>,pub generation:u32,pub retired:bool,#[serde(default)]pub operation:Option<crate::waiting_local::Mutation>,#[serde(default)]pub attach:Option<AttachOriginal>}
#[derive(Clone,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct AttachOriginal{pub request:crate::protocol_g2_next::wire::Request,pub original:w::WaitingOriginal}
impl AttachOriginal{
 pub fn capture(scope:&Scope,request:crate::protocol_g2_next::wire::Request,session:&str)->Result<Self,String>{crate::protocol_g2_next::request(&serde_json::to_vec(&request).map_err(|_|"Original attach encoding")?).map_err(|_|"Original attach shape")?;let a=request.game_attach.as_ref().ok_or("Original gameAttach absent")?;if request.service_id.as_deref()!=Some(&scope.service)||request.service_epoch.as_deref()!=Some(&scope.service_epoch)||request.session_epoch.as_deref()!=Some(&scope.desktop_epoch)||session!=scope.desktop||a.preparation_id.as_deref()!=Some(&scope.preparation){return Err("Original gameAttach scope differs".into())}let original=w::WaitingOriginal{account_id:Some(scope.account.clone()),device_id:Some(scope.device.to_string()),original_session_id:Some(session.into()),original_session_epoch:request.session_epoch.clone(),original_service_epoch:request.service_epoch.clone(),request_id:request.request_id.clone(),kind:Some("gameAttach".into()),fingerprint:Some(crate::protocol_connection::canonical_fingerprint(&serde_json::to_vec(&request).map_err(|_|"Attach encoding")?)?),waiting_id:None};protocol::validate("WaitingOriginal",&original)?;Ok(Self{request,original})}
 pub fn validate(&self,scope:&Scope)->Result<(),String>{let rebuilt=Self::capture(scope,self.request.clone(),self.original.original_session_id.as_deref().ok_or("Original attach actor absent")?)?;if serde_json::to_value(&rebuilt.original).ok()!=serde_json::to_value(&self.original).ok(){return Err("Original attach metadata differs".into())}Ok(())}
}
impl Drop for Record{fn drop(&mut self){if let Some(p)=self.proof.as_mut(){p.zeroize()}if let Some(p)=self.request.pending_recover.as_mut().and_then(|r|r.pending_proof.as_mut()){p.zeroize()}if let Some(p)=self.request.pending_offline.as_mut().and_then(|r|r.pending_proof.as_mut()){p.zeroize()}}}
impl Record{
 pub fn original(&self)->w::WaitingOriginal{w::WaitingOriginal{account_id:Some(self.scope.account.clone()),device_id:Some(self.scope.device.to_string()),original_session_id:Some(self.original_session.clone()),original_session_epoch:self.request.session_epoch.clone(),original_service_epoch:self.request.service_epoch.clone(),request_id:self.request.request_id.clone(),kind:Some("reserve".into()),fingerprint:Some(self.fingerprint.clone()),waiting_id:None}}
 pub fn ready(&self)->bool{!self.retired&&self.intent.is_some()&&self.proof.as_ref().is_some_and(|p|p.len()==43)&&self.generation>0}
 pub fn validate(&self)->Result<(),String>{if let Some(op)=&self.operation{op.validate(&self.scope)?;if op.request.pending_recover.is_none()&&op.request.pending_offline.is_none(){return Err("Pending operation kind differs".into())}}if let Some(a)=&self.attach{a.validate(&self.scope)?}protocol::validate("Request",&self.request)?;if self.world.is_nil()||self.request.reserve.as_ref().is_none_or(|r|r.preparation_id.as_deref()!=Some(&self.scope.preparation)||r.context_id.as_deref()!=Some(&self.world.simple().to_string())||r.world_token!=r.context_id)||self.request.service_id.as_deref()!=Some(&self.scope.service)||self.request.service_epoch.as_deref()!=Some(&self.scope.service_epoch)||self.request.session_epoch.as_deref()!=Some(&self.scope.desktop_epoch)||self.original_session!=self.scope.desktop||self.fingerprint!=crate::protocol_connection::canonical_fingerprint(&serde_json::to_vec(&self.request).map_err(|_|"Reserve original encoding")?)?{return Err("Pending exact original scope differs".into())}
  if let Some(i)=&self.intent{protocol::validate("PendingIntent",i)?;if i.account_id.as_deref()!=Some(&self.scope.account)||i.device_id.as_deref()!=Some(&self.scope.device.to_string())||i.service_id.as_deref()!=Some(&self.scope.service)||i.service_epoch.as_deref()!=Some(&self.scope.service_epoch)||i.preparation_id.as_deref()!=Some(&self.scope.preparation)||i.room_id.as_deref()!=Some(&self.scope.room)||i.run_id.as_deref()!=Some(&self.scope.run)||i.run_epoch.as_deref()!=Some(&self.scope.run_epoch)||i.config_revision.map(u64::from)!=Some(self.scope.config)||i.config_digest.as_deref()!=Some(&self.scope.config_digest)||i.original_desktop_id.as_deref()!=Some(&self.scope.desktop)||i.original_desktop_epoch.as_deref()!=Some(&self.scope.desktop_epoch)||i.world_token!=self.request.reserve.as_ref().and_then(|r|r.world_token.clone())||i.context_id!=i.world_token{return Err("Pending canonical original differs".into())}}
  if self.proof.as_ref().is_some_and(|p|p.len()!=43||!p.bytes().all(|c|c.is_ascii_alphanumeric()||c==b'-'||c==b'_'))||self.proof.is_some()&&self.intent.is_none(){return Err("Pending proof bound".into())}Ok(())
 }
}
pub fn save<S:CredentialStore>(store:&S,r:&Record)->Result<(),String>{r.validate()?;let bytes=zeroize::Zeroizing::new(serde_json::to_vec(r).map_err(|_|"Pending record encoding")?);protected_chunks::save(store,&r.scope,"nt2-startup-reservation-v1",r.world,&bytes)}
pub fn load<S:CredentialStore>(store:&S,scope:&Scope,world:uuid::Uuid)->Result<Option<Record>,String>{let Some(bytes)=protected_chunks::load(store,scope,"nt2-startup-reservation-v1",world)?else{return Ok(None)};let r:Record=serde_json::from_slice(&bytes).map_err(|_|"Pending record corrupt")?;if r.scope!=*scope||r.world!=world{return Err("Pending original issuer/world differs".into())}r.validate()?;Ok(Some(r))}
#[cfg(test)]mod tests{
 use super::*;use std::sync::Mutex;
 #[derive(Default)]struct Store(Mutex<std::collections::BTreeMap<String,Vec<u8>>>);
 impl CredentialStore for Store{fn save(&self,p:&crate::secrets::ServiceProfile,b:&crate::secrets::SecretBlob)->Result<(),crate::secrets::StoreError>{self.0.lock().unwrap().insert(format!("{p:?}"),b.bytes().to_vec());Ok(())}fn load(&self,p:&crate::secrets::ServiceProfile)->Result<Option<crate::secrets::SecretBlob>,crate::secrets::StoreError>{self.0.lock().unwrap().get(&format!("{p:?}")).map(|b|crate::secrets::SecretBlob::new(b.clone())).transpose()}fn delete(&self,p:&crate::secrets::ServiceProfile)->Result<(),crate::secrets::StoreError>{self.0.lock().unwrap().remove(&format!("{p:?}"));Ok(())}}
 fn original()->Record{
  let gold:serde_json::Value=serde_json::from_str(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../packages/contracts/g3-waiting/golden.json"))).unwrap();let mut i:w::PendingIntent=serde_json::from_value(gold["fixtures"].as_array().unwrap().iter().find(|v|v["json"]["intent"]["pendingId"].is_string()&&v["json"]["intent"]["seedPolicy"]=="individual-random").unwrap()["json"]["intent"].clone()).unwrap();let world=uuid::Uuid::new_v4();let device=uuid::Uuid::new_v4();i.world_token=Some(world.simple().to_string());i.context_id=i.world_token.clone();i.device_id=Some(device.to_string());let s=Scope{origin:"https://pending.invalid".into(),service:i.service_id.clone().unwrap(),service_epoch:i.service_epoch.clone().unwrap(),account:i.account_id.clone().unwrap(),device,desktop:i.original_desktop_id.clone().unwrap(),desktop_epoch:i.original_desktop_epoch.clone().unwrap(),room:i.room_id.clone().unwrap(),run:i.run_id.clone().unwrap(),run_epoch:i.run_epoch.clone().unwrap(),config:u64::from(i.config_revision.unwrap()),config_digest:i.config_digest.clone().unwrap(),preparation:i.preparation_id.clone().unwrap()};let request=w::Request{major:Some(1),revision:Some(protocol::REVISION.into()),service_id:Some(s.service.clone()),service_epoch:Some(s.service_epoch.clone()),session_epoch:Some(s.desktop_epoch.clone()),request_id:Some(uuid::Uuid::new_v4().to_string()),reserve:Some(w::Reserve{preparation_id:Some(s.preparation.clone()),world_token:i.world_token.clone(),context_id:i.context_id.clone()}),..Default::default()};Record{scope:s.clone(),world,original_session:s.desktop,request:request.clone(),fingerprint:crate::protocol_connection::canonical_fingerprint(&serde_json::to_vec(&request).unwrap()).unwrap(),intent:Some(i),proof:Some("p".repeat(43)),generation:1,retired:false,operation:None,attach:None}
 }
 #[test]fn startup_repair_pending_original_proof_scope_and_unknown_individual_seed_survive_restart(){
  let store=Store::default();let r=original();r.validate().unwrap();assert!(r.ready());assert!(r.intent.as_ref().unwrap().actual_seed.is_none());save(&store,&r).unwrap();let cold=load(&store,&r.scope,r.world).unwrap().unwrap();assert_eq!(serde_json::to_vec(&cold.request).unwrap(),serde_json::to_vec(&r.request).unwrap());assert_eq!(cold.fingerprint,r.fingerprint);assert_eq!(cold.proof,r.proof);assert!(cold.intent.as_ref().unwrap().actual_seed.is_none());
  let mut other=r.scope.clone();other.account=uuid::Uuid::new_v4().to_string();assert!(load(&store,&other,r.world).unwrap().is_none());other=r.scope.clone();other.desktop_epoch=uuid::Uuid::new_v4().to_string();assert!(load(&store,&other,r.world).is_err());let mut altered=r.clone();altered.request.reserve.as_mut().unwrap().context_id=Some(uuid::Uuid::new_v4().simple().to_string());assert!(save(&store,&altered).is_err());let mut altered=r.clone();altered.fingerprint="f".repeat(64);assert!(save(&store,&altered).is_err());let mut retired=r.clone();retired.retired=true;assert!(!retired.ready());save(&store,&retired).unwrap();assert!(!load(&store,&r.scope,r.world).unwrap().unwrap().ready());
 }
}
